  function ProfileVoiceEntryButton({ onField, label = "Speak your info — name, age, height, weight…" }) {
    const [recording, setRecording] = useState(false);
    const [busy, setBusy] = useState(false);
    const [error, setError] = useState("");
    const [heardText, setHeardText] = useState("");
    const [filledSummary, setFilledSummary] = useState("");
    const recorderRef = useRef(null);
    const chunksRef = useRef([]);
    const { level: talkLevel, attach: attachTalkLevel, detach: detachTalkLevel } = useTalkingLevel();

    async function startRecording() {
      setError(""); setHeardText(""); setFilledSummary("");
      if (!navigator.mediaDevices || !window.MediaRecorder) {
        setError("Voice input isn't supported in this browser.");
        return;
      }
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        attachTalkLevel(stream);
        const recorder = new MediaRecorder(stream);
        chunksRef.current = [];
        recorder.ondataavailable = (ev) => { if (ev.data && ev.data.size > 0) chunksRef.current.push(ev.data); };
        recorder.onstop = async () => {
          stream.getTracks().forEach((t) => t.stop());
          detachTalkLevel();
          const blob = new Blob(chunksRef.current, { type: recorder.mimeType || "audio/webm" });
          await sendForParsing(blob);
        };
        recorderRef.current = recorder;
        recorder.start();
        setRecording(true);
      } catch (e) {
        setError("Couldn't access the microphone — check your browser's permission.");
      }
    }

    function stopRecording() {
      if (recorderRef.current && recording) {
        recorderRef.current.stop();
        setRecording(false);
      }
    }

    async function sendForParsing(blob) {
      if (!sb) { setError("Backend not configured yet."); return; }
      setBusy(true);
      setError("");
      try {
        const audio = await blobToBase64(blob);
        const { data, error: err } = await sb.functions.invoke("voice-profile-entry", {
          body: { audio, mimeType: blob.type || "audio/webm" }
        });
        if (err || !data || data.error) {
          setError("Couldn't understand that — try again.");
          setBusy(false);
          return;
        }
        setHeardText(data.heardText || "");
        const FIELD_MAP = [
          ["name", "client_name"], ["lastName", "last_name"], ["age", "age"],
          ["birthday", "birthday"], ["gender", "gender"], ["phone", "phone"],
          ["heightCm", "height_cm"], ["weightKg", "weight_kg"],
          ["daysPerWeek", "days_per_week"], ["goal", "goal"]
        ];
        const filled = [];
        FIELD_MAP.forEach(([key, dbField]) => {
          let v = data[key];
          if (v === undefined || v === null || v === "") return;
          if (dbField === "age" && (v < AGE_RANGE[0] || v > AGE_RANGE[1])) return;
          if (dbField === "height_cm" && (v < HEIGHT_CM_RANGE[0] || v > HEIGHT_CM_RANGE[1])) return;
          if (dbField === "weight_kg" && (v < WEIGHT_KG_RANGE[0] || v > WEIGHT_KG_RANGE[1])) return;
          if (dbField === "days_per_week") v = Math.max(1, Math.min(7, Math.round(Number(v))));
          if (dbField === "gender" && !["Male", "Female", "Other", "Prefer not to say"].includes(v)) return;
          onField(dbField, v);
          filled.push(dbField);
        });
        setFilledSummary(filled.length
          ? `Filled: ${filled.map((f) => PROFILE_VOICE_FIELD_LABELS[f] || f).join(", ")}`
          : "Didn't catch any info fields in that — try again.");
      } catch (e) {
        setError("Couldn't understand that — try again.");
      }
      setBusy(false);
    }

    return e("div", { style: { marginBottom: 14 } },
      e("button", {
        type: "button",
        onMouseDown: (ev) => ev.preventDefault(),
        onClick: recording ? stopRecording : startRecording,
        disabled: busy,
        style: {
          display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
          width: "100%", padding: "13px 16px", borderRadius: 12,
          background: recording ? C.criticalSoft : C.brandSoft,
          border: `1.5px solid ${recording ? C.critical : C.brand}`,
          color: recording ? C.critical : C.brand,
          fontFamily: "'Inter', sans-serif", fontWeight: 700, fontSize: 13.5,
          cursor: busy ? "default" : "pointer"
        }
      },
        recording ? e(TalkingTrainerEmoji, { level: talkLevel, size: 19 }) : busy ? e(VoiceLoadingDots, { size: 6, color: C.brand }) : e(Icon, { name: "mic", size: 17 }),
        recording ? "Stop — I'm done" : busy ? "Got it — filling it in…" : label
      ),
      error && e("div", { style: { ...styles.inlineError, marginTop: 6 } }, error),
      heardText && !error && e("div", { style: { fontSize: 11.5, color: C.ink3, marginTop: 6, fontStyle: "italic" } }, `Heard: "${heardText}"`),
      filledSummary && !error && e("div", { style: { fontSize: 11.5, color: C.good, marginTop: 3, fontWeight: 600 } }, filledSummary)
    );
  }

  function CheckInVoiceCapture({ onSave, saving }) {
    const [recording, setRecording] = useState(false);
    const [busy, setBusy] = useState(false);
    const [error, setError] = useState("");
    // Sept 12 2026, Jimmy: dashboard top section pass — a transcription no
    // longer saves itself straight away. null = mic mode; a string (even
    // empty) = the editable "here's what we heard" preview, so a mis-heard
    // word can be fixed before it lands in the client's check-in history.
    const [heardText, setHeardText] = useState(null);
    const recorderRef = useRef(null);
    const chunksRef = useRef([]);
    const { level: talkLevel, attach: attachTalkLevel, detach: detachTalkLevel } = useTalkingLevel();

    async function startRecording() {
      setError("");
      if (!navigator.mediaDevices || !window.MediaRecorder) {
        setError("Voice input isn't supported in this browser.");
        return;
      }
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        attachTalkLevel(stream);
        const recorder = new MediaRecorder(stream);
        chunksRef.current = [];
        recorder.ondataavailable = (ev) => { if (ev.data && ev.data.size > 0) chunksRef.current.push(ev.data); };
        recorder.onstop = async () => {
          stream.getTracks().forEach((t) => t.stop());
          detachTalkLevel();
          const blob = new Blob(chunksRef.current, { type: recorder.mimeType || "audio/webm" });
          await sendForTranslation(blob);
        };
        recorderRef.current = recorder;
        recorder.start();
        setRecording(true);
      } catch (e) {
        setError("Couldn't access the microphone — check your browser's permission.");
      }
    }

    function stopRecording() {
      if (recorderRef.current && recording) {
        recorderRef.current.stop();
        setRecording(false);
      }
    }

    async function sendForTranslation(blob) {
      if (!sb) { setError("Backend not configured yet."); return; }
      setBusy(true);
      setError("");
      try {
        const audio = await blobToBase64(blob);
        const { data, error: err } = await sb.functions.invoke("voice-log-entry", {
          body: { audio, mimeType: blob.type || "audio/webm", exerciseNames: [] }
        });
        if (err || !data || data.error || !data.heardText) {
          setError("Couldn't understand that — try again.");
        } else {
          setHeardText(data.heardText);
        }
      } catch (e) {
        setError("Couldn't understand that — try again.");
      }
      setBusy(false);
    }

    async function confirmSave() {
      if (!heardText || !heardText.trim()) return;
      const ok = await onSave(heardText);
      if (ok) setHeardText(null); // failed save leaves the draft on screen so nothing typed is lost
    }

    const isBusy = busy || saving;

    if (heardText !== null) {
      // Re-detects live as the text is edited, so fixing a mis-heard word
      // (or the client tweaking their own wording) updates the emoji too.
      const mood = detectMoodEmoji(heardText);
      return e("div", { style: { marginBottom: 12 } },
        e("p", { style: { margin: "0 0 6px", fontSize: 12, color: C.ink3, fontWeight: 600, display: "flex", alignItems: "center", gap: 6 } },
          "Here's what we heard — edit if needed",
          mood && e("span", { style: { fontSize: 16 } }, mood)
        ),
        e("textarea", {
          autoFocus: true,
          value: heardText,
          onChange: (ev) => setHeardText(ev.target.value),
          disabled: saving,
          style: { ...styles.input, width: "100%", minHeight: 70, resize: "vertical", fontFamily: "'Inter', sans-serif" }
        }),
        e("div", { style: { display: "flex", gap: 10, marginTop: 8 } },
          e("button", { type: "button", style: { ...styles.ghostPillBtn, flex: 1 }, onClick: () => setHeardText(null), disabled: saving }, "Discard"),
          e("button", {
            type: "button",
            style: { ...styles.ghostPillBtn, flex: 1, background: C.brand, color: C.brandInk },
            onClick: confirmSave,
            disabled: saving || !heardText.trim()
          }, saving ? "Saving…" : "Save")
        ),
        error && e("div", { style: { ...styles.inlineError, marginTop: 6 } }, error)
      );
    }

    return e("div", { style: { marginBottom: 12 } },
      e("button", {
        type: "button",
        onMouseDown: (ev) => ev.preventDefault(),
        onClick: recording ? stopRecording : startRecording,
        disabled: isBusy,
        style: {
          display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
          width: "100%", padding: "12px 16px", borderRadius: 12,
          background: recording ? C.criticalSoft : C.brandSoft,
          border: `1.5px solid ${recording ? C.critical : C.brand}`,
          color: recording ? C.critical : C.brand,
          fontFamily: "'Inter', sans-serif", fontWeight: 700, fontSize: 13,
          cursor: isBusy ? "default" : "pointer"
        }
      },
        recording ? e(TalkingTrainerEmoji, { level: talkLevel, size: 18 }) : busy ? e(VoiceLoadingDots, { size: 6, color: C.brand }) : e(Icon, { name: "mic", size: 16 }),
        recording ? "Stop — I'm done" : busy ? "Got it — one sec…" : "How are you feeling today?"
      ),
      error && e("div", { style: { ...styles.inlineError, marginTop: 6 } }, error)
    );
  }

